$ErrorActionPreference = 'Stop'; $ProgressPreference = 'SilentlyContinue'; {{#configured}}$path = {{path}}{{/configured}}{{^configured}}$command = Get-Command herdr.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1; $path = if ($command) { $command.Source } else { Join-Path $env:LOCALAPPDATA 'Programs\Herdr\bin\herdr.exe' }{{/configured}}; if (!(Test-Path -LiteralPath $path -PathType Leaf)) { throw 'roamgate-windows-herdr-unavailable' }; $check = & $path remote-api-bridge --check; if ($LASTEXITCODE -ne 0 -or $check -ne 'herdr-api-bridge-v1') { throw 'roamgate-windows-herdr-unavailable' }; $status = & $path --session {{session}} status server --json; if ($LASTEXITCODE -ne 0) { throw 'roamgate-windows-status-failed' }; if (!($status | ConvertFrom-Json).running) { throw 'roamgate-windows-session-unavailable' }; [Console]::Out.WriteLine('roamgate-herdr-path:' + [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($path)))